function blockMessage(form: FormState): string {
  if (form.maKh.trim().length === 0) return 'Bạn chưa nhập mã đối tượng';
  if (form.maNx.trim().length === 0) return 'Bạn chưa nhập tài có ';
  if (!form.suaThue) {
    if (form.soCt0.trim().length === 0) return 'Bạn chưa nhập số hóa đơn VAT';
    if (form.soSeri0.trim().length === 0) return 'Bạn chưa nhập số seri hóa đơn VAT';
    if (form.ngayCt0.trim().length === 0 || form.ngayCt0.trim() === INVOICE_SENTINEL) return 'Bạn chưa nhập ngày hóa đơn VAT';
  }
  for (const line of form.lines) {
    if (line.maKhoI.trim().length === 0) return 'Bạn chưa nhập kho nhập ';
    if (line.tkVt.trim().length === 0) return 'Bạn chưa nhập tài khoản nợ';
    if (line.maNxI.trim().length === 0) return 'Bạn chưa nhập tài khoản nợ của nghiệp vụ xuất kho';
  }
  return '';
}

